/** Signature lines for a person: name, company, phone. Three lines and nothing else. */
function signatureLines(name, cfg = BRAND_CONFIG) {
  return [String(name || cfg.signatureName).trim() || cfg.signatureName, cfg.brand, cfg.phone];
}

/** The CAN-SPAM footer, as the exact lines that end every cold email. */
function canspamFooterLines(cfg = BRAND_CONFIG) {
  return [`${cfg.legalEntity}, ${cfg.postalAddress}`, cfg.unsubscribeLine];
}

/** The same footer as the HTML Instantly takes in a step body. */
function canspamFooterHtml(cfg = BRAND_CONFIG) {
  return "<div><br /></div>" + canspamFooterLines(cfg).map((l) => `<div>${l}</div>`).join("");
}

